import * as THREE from "three";
import SceneManager from "./sceneManager";
import CaseManager from "./case/caseManager";
import KeyManager from "./key/keyManager";
import * as webfont from "webfontloader";
import { GLTFExporter } from 'three/examples/jsm/exporters/GLTFExporter.js';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
const SCREEN_SCALE = 50;

export default (element) => {
  //ensure fonts loaded for canvas textures
  webfont.load({
    custom: {
      families: ["legends", "Varela Round"],
    },
    active: function () {
      //MAIN THREE JS SETUP
      //-------------------------------------
      const ThreeApp = new SceneManager({
        scale: SCREEN_SCALE,
        el: element,
      });

       const CASE = new CaseManager({
        scene: ThreeApp.scene
      });

      const KEYS = new KeyManager({
        scene: ThreeApp.scene, caseManager: CASE
      });

     
      CASE.keys = KEYS; 

      window.THREE = THREE;
      window.ThreeApp = ThreeApp;
      window.CASE = CASE;
      window.KEYS = KEYS;

      let newKeyModel = null;
      let isLoadingModel = false;

      const DEFAULT_BASE_TRANSFORM = {
        x: -0.60,
        y: -0.35,
        z: 0.20,
        rx: (-86 * Math.PI) / 180,
        ry: 0,
        rz: 0,
        scaleX: 1.14,
        scaleZ: 1.14,
        version: 4,
      };

      const KEY_CLUSTER_MAP = {
        nav_cluster: ["KC_HOME", "KC_END", "KC_PGUP"],
        arrow_cluster: ["KC_UP", "KC_DOWN", "KC_LEFT", "KC_RGHT"],
        rctl: ["KC_RCTL"],
      };

      const DEFAULT_CLUSTER_OFFSETS = {
        nav_cluster: { x: -0.42, z: 0.00 },
        arrow_cluster: { x: -0.16, z: -0.09 },
        rctl: { x: -0.67, z: 0.00 },
      };

      const getSavedClusterOffsets = () => {
        try {
          const raw = localStorage.getItem("keysim_key_cluster_offsets");
          if (raw) {
            const parsed = JSON.parse(raw);
            if (parsed.version === 7) {
              const nav = parsed.nav_cluster || parsed.home_end_pgup || {};
              const arrow = parsed.arrow_cluster || {};
              const rctl = parsed.rctl || parsed.right_control || {};
              return {
                nav_cluster: { ...DEFAULT_CLUSTER_OFFSETS.nav_cluster, ...nav },
                arrow_cluster: { ...DEFAULT_CLUSTER_OFFSETS.arrow_cluster, ...arrow },
                rctl: { ...DEFAULT_CLUSTER_OFFSETS.rctl, ...rctl },
              };
            }
          }
        } catch (e) {}
        return {
          nav_cluster: { ...DEFAULT_CLUSTER_OFFSETS.nav_cluster },
          arrow_cluster: { ...DEFAULT_CLUSTER_OFFSETS.arrow_cluster },
          rctl: { ...DEFAULT_CLUSTER_OFFSETS.rctl },
        };
      };

      let currentClusterOffsets = getSavedClusterOffsets();

      const applyKeyClusterOffsets = (isNew = isCurrentNewModel) => {
        if (!KEYS || !KEYS.components) return;
        for (const [clusterId, keyCodes] of Object.entries(KEY_CLUSTER_MAP)) {
          const offset = isNew ? (currentClusterOffsets[clusterId] || { x: 0, z: 0 }) : { x: 0, z: 0 };
          for (const code of keyCodes) {
            const keys = KEYS.components.filter((k) => (k._origCode || k.code) === code);
            for (const k of keys) {
              if (k && k.cap) {
                if (k.cap._origX === undefined || (k.cap._origX > 10 && k.cap.position.x < 10)) {
                  k.cap._origX = k.cap.position.x;
                  k.cap._origZ = k.cap.position.z;
                }
                k.cap.position.x = Number((k.cap._origX + offset.x).toFixed(4));
                k.cap.position.z = Number((k.cap._origZ + offset.z).toFixed(4));
              }
            }
          }
        }
      };

      window.applyKeyClusterOffsets = applyKeyClusterOffsets;

      const NEW_MODEL_HIDDEN_KEYS = [
        "KC_DEL",
        "KC_PGDN",
        "KC_FN",
        "KC_PSCR",
        "KC_SLCK",
        "KC_INS",
      ];

      let isCurrentNewModel = true;
      window.isCurrentNewModel = isCurrentNewModel;

      const getNavClusterKeys = () => {
        if (!KEYS || !KEYS.components) return null;
        const home = KEYS.components.find((k) => k._navRole === 'HOME' || k.code === 'KC_HOME');
        const end = KEYS.components.find((k) => k._navRole === 'END' || k.code === 'KC_END');
        const pgup = KEYS.components.find((k) => k._navRole === 'PGUP' || (k.code === 'KC_PGUP' && (k.options?.dimensions?.row === 3 || (k.cap && k.cap.position.z > 0))));

        if (home && !home._navRole) {
          home._navRole = 'HOME';
          home._origCode = 'KC_HOME';
        }
        if (end && !end._navRole) {
          end._navRole = 'END';
          end._origCode = 'KC_END';
        }
        if (pgup && !pgup._navRole) {
          pgup._navRole = 'PGUP';
          pgup._origCode = 'KC_PGUP';
        }
        return { home, end, pgup };
      };

      const applyNewModelNavClusterMapping = (isNew) => {
        const cluster = getNavClusterKeys();
        if (!cluster) return;
        const { home, end, pgup } = cluster;

        if (isNew) {
          // In New Model:
          // Home -> Delete
          if (home) {
            home.mappedCode = "KC_DEL";
            if (home.cap) home.cap.visible = true;
            if (typeof home.updateColors === "function") home.updateColors(false, true);
          }
          // End -> PgUp
          if (end) {
            end.mappedCode = "KC_PGUP";
            if (end.cap) end.cap.visible = true;
            if (typeof end.updateColors === "function") end.updateColors(false, true);
          }
          // PgUp -> PgDn
          if (pgup) {
            pgup.mappedCode = "KC_PGDN";
            if (pgup.cap) pgup.cap.visible = true;
            if (typeof pgup.updateColors === "function") pgup.updateColors(false, true);
          }
        } else {
          // Revert for Classic Mode:
          if (home) {
            home.mappedCode = null;
            if (home.cap) home.cap.visible = true;
            if (typeof home.updateColors === "function") home.updateColors(false, true);
          }
          if (end) {
            end.mappedCode = null;
            if (end.cap) end.cap.visible = true;
            if (typeof end.updateColors === "function") end.updateColors(false, true);
          }
          if (pgup) {
            pgup.mappedCode = null;
            if (pgup.cap) pgup.cap.visible = true;
            if (typeof pgup.updateColors === "function") pgup.updateColors(false, true);
          }
        }
      };

      const applyNewModelModifiers = (isNew) => {
        if (!KEYS || !KEYS.components) return;
        const lalt = KEYS.getKey("KC_LALT");
        const lctl = KEYS.getKey("KC_LCTL");
        const ralt = KEYS.getKey("KC_RALT");
        const rctl = KEYS.getKey("KC_RCTL");

        if (isNew) {
          if (ralt && ralt.cap && lalt && lalt.cap) {
            if (!ralt._origGeom) ralt._origGeom = ralt.cap.geometry;
            if (!ralt._origW) ralt._origW = ralt.w;
            if (ralt.options && ralt.options.dimensions) ralt.options.dimensions.w = 1.25;
            ralt.cap.geometry = lalt.cap.geometry.clone();
            ralt.cap.material = lalt.cap.material;
            // Position of old right alt
            ralt.cap.position.x = 1.5919688;
            ralt.cap.position.z = 2.0924225742;
            ralt.cap.position.y = 0.1;
            ralt.cap._origX = 1.5919688;
            ralt.cap._origZ = 2.0924225742;
            ralt.cap.visible = true;
          }

          if (rctl && rctl.cap && lctl && lctl.cap) {
            if (!rctl._origGeom) rctl._origGeom = rctl.cap.geometry;
            if (!rctl._origW) rctl._origW = rctl.w;
            if (rctl.options && rctl.options.dimensions) rctl.options.dimensions.w = 1.25;
            rctl.cap.geometry = lctl.cap.geometry.clone();
            rctl.cap.material = lctl.cap.material;
            // Position of old right ctrl
            rctl.cap.position.x = 3.4877991;
            rctl.cap.position.z = 2.0924225742;
            rctl.cap.position.y = 0.1;
            rctl.cap._origX = 3.4877991;
            rctl.cap._origZ = 2.0924225742;
            rctl.cap.visible = true;
          }
        } else {
          if (ralt && ralt.cap) {
            if (ralt._origGeom) ralt.cap.geometry = ralt._origGeom;
            if (ralt._origW) {
              if (ralt.options && ralt.options.dimensions) ralt.options.dimensions.w = ralt._origW;
            }
            if (typeof ralt.updateColors === "function") ralt.updateColors();
            if (ralt.cap._origX !== undefined) {
              ralt.cap.position.x = ralt.cap._origX;
              ralt.cap.position.z = ralt.cap._origZ;
            }
            ralt.cap.visible = true;
          }
          if (rctl && rctl.cap) {
            if (rctl._origGeom) rctl.cap.geometry = rctl._origGeom;
            if (rctl._origW) {
              if (rctl.options && rctl.options.dimensions) rctl.options.dimensions.w = rctl._origW;
            }
            if (typeof rctl.updateColors === "function") rctl.updateColors();
            if (rctl.cap._origX !== undefined) {
              rctl.cap.position.x = rctl.cap._origX;
              rctl.cap.position.z = rctl.cap._origZ;
            }
            rctl.cap.visible = true;
          }
        }
      };

      const updateKeyVisibility = (isNew = isCurrentNewModel) => {
        isCurrentNewModel = !!isNew;
        window.isCurrentNewModel = isCurrentNewModel;
        if (!KEYS || !KEYS.components) return;
        getNavClusterKeys();
        for (const k of KEYS.components) {
          if (!k || !k.cap) continue;
          if (k.code === "KC_NO") {
            k.cap.visible = false;
            continue;
          }
          const isNavClusterKey = k._navRole === 'HOME' || k._navRole === 'END' || k._navRole === 'PGUP';
          const shouldHide =
            !isNavClusterKey &&
            (NEW_MODEL_HIDDEN_KEYS.includes(k._origCode || k.code) ||
            // Hide middle NoName key between RAlt (1.59) and RCtrl (3.49)
            (k.cap.position.z > 1.8 && k.cap.position.x > 2.0 && k.cap.position.x < 3.0));

          if (isCurrentNewModel && shouldHide) {
            k.cap.visible = false;
          } else {
            k.cap.visible = true;
          }
        }
        applyNewModelModifiers(isCurrentNewModel);
        applyNewModelNavClusterMapping(isCurrentNewModel);
        applyKeyClusterOffsets(isCurrentNewModel);
      };

      window.updateKeyVisibility = updateKeyVisibility;

      const getSavedBaseTransform = () => {
        try {
          const raw = localStorage.getItem("keysim_base_transform");
          if (raw) {
            const parsed = JSON.parse(raw);
            if (parsed.version === 4) {
              return { ...DEFAULT_BASE_TRANSFORM, ...parsed };
            }
          }
        } catch (e) {}
        return { ...DEFAULT_BASE_TRANSFORM };
      };

      let currentBaseTransform = getSavedBaseTransform();

      const applyBaseTransform = (target) => {
        if (!target) return;
        target.position.set(
          currentBaseTransform.x,
          currentBaseTransform.y,
          currentBaseTransform.z
        );
        target.rotation.set(
          currentBaseTransform.rx,
          currentBaseTransform.ry,
          currentBaseTransform.rz
        );
        const baseFactor = target._baseScale !== undefined ? target._baseScale : 0.03937;
        const sx = currentBaseTransform.scaleX || currentBaseTransform.scale || 1.14;
        const sz = currentBaseTransform.scaleZ || currentBaseTransform.scale || 1.14;
        // Local X = World X (width), Local Y = World Z (depth), Local Z = World Y (thickness)
        target.scale.set(baseFactor * sx, baseFactor * sz, baseFactor * 1.14);
      };

      const emitBaseTransformUpdate = () => {
        try {
          localStorage.setItem("keysim_base_transform", JSON.stringify(currentBaseTransform));
          localStorage.setItem("keysim_key_cluster_offsets", JSON.stringify({ ...currentClusterOffsets, version: 7 }));
          if (typeof window !== "undefined" && window.parent && window.parent !== window) {
            window.parent.postMessage({
              type: "KEYSIM_BASE_TRANSFORM_UPDATE",
              transform: {
                x: Number(currentBaseTransform.x.toFixed(3)),
                y: Number(currentBaseTransform.y.toFixed(3)),
                z: Number(currentBaseTransform.z.toFixed(3)),
                rxDeg: Number(((currentBaseTransform.rx * 180) / Math.PI).toFixed(1)),
                rxRad: Number(currentBaseTransform.rx.toFixed(4)),
                scaleX: Number((currentBaseTransform.scaleX || 1.14).toFixed(3)),
                scaleZ: Number((currentBaseTransform.scaleZ || 1.14).toFixed(3)),
                scale: Number((currentBaseTransform.scaleX || 1.14).toFixed(3)),
                clusterOffsets: {
                  nav_cluster: { x: Number((currentClusterOffsets.nav_cluster?.x || 0).toFixed(3)), z: Number((currentClusterOffsets.nav_cluster?.z || 0).toFixed(3)) },
                  arrow_cluster: { x: Number((currentClusterOffsets.arrow_cluster?.x || 0).toFixed(3)), z: Number((currentClusterOffsets.arrow_cluster?.z || 0).toFixed(3)) },
                  rctl: { x: Number((currentClusterOffsets.rctl?.x || 0).toFixed(3)), z: Number((currentClusterOffsets.rctl?.z || 0).toFixed(3)) },
                }
              }
            }, "*");
          }
        } catch (e) {}
      };

      window.getBaseTransform = () => ({
        x: Number(currentBaseTransform.x.toFixed(3)),
        y: Number(currentBaseTransform.y.toFixed(3)),
        z: Number(currentBaseTransform.z.toFixed(3)),
        rxDeg: Number(((currentBaseTransform.rx * 180) / Math.PI).toFixed(1)),
        rxRad: Number(currentBaseTransform.rx.toFixed(4)),
        scaleX: Number((currentBaseTransform.scaleX || 1.14).toFixed(3)),
        scaleZ: Number((currentBaseTransform.scaleZ || 1.14).toFixed(3)),
        scale: Number((currentBaseTransform.scaleX || 1.14).toFixed(3)),
        clusterOffsets: {
          nav_cluster: { x: Number((currentClusterOffsets.nav_cluster?.x || 0).toFixed(3)), z: Number((currentClusterOffsets.nav_cluster?.z || 0).toFixed(3)) },
          arrow_cluster: { x: Number((currentClusterOffsets.arrow_cluster?.x || 0).toFixed(3)), z: Number((currentClusterOffsets.arrow_cluster?.z || 0).toFixed(3)) },
          rctl: { x: Number((currentClusterOffsets.rctl?.x || 0).toFixed(3)), z: Number((currentClusterOffsets.rctl?.z || 0).toFixed(3)) },
        }
      });

      window.adjustBaseTransform = (dx = 0, dy = 0, dz = 0, drx = 0, ds = 0, dsx = 0, dsz = 0, target = "base") => {
        const clusterTarget = (target === "nav_cluster" || target === "home_end_pgup" || target === "pg_cluster")
          ? "nav_cluster"
          : (target === "rctl" || target === "right_control")
            ? "rctl"
            : target;
        if (clusterTarget && clusterTarget !== "base" && currentClusterOffsets[clusterTarget]) {
          currentClusterOffsets[clusterTarget].x = Number((currentClusterOffsets[clusterTarget].x + dx).toFixed(4));
          currentClusterOffsets[clusterTarget].z = Number((currentClusterOffsets[clusterTarget].z + dz).toFixed(4));
          applyKeyClusterOffsets();
          emitBaseTransformUpdate();
          return;
        }

        currentBaseTransform.x = Number((currentBaseTransform.x + dx).toFixed(4));
        currentBaseTransform.y = Number((currentBaseTransform.y + dy).toFixed(4));
        currentBaseTransform.z = Number((currentBaseTransform.z + dz).toFixed(4));
        currentBaseTransform.rx = Number((currentBaseTransform.rx + drx).toFixed(5));
        if (ds) {
          currentBaseTransform.scaleX = Math.max(0.1, Number(((currentBaseTransform.scaleX || 1.14) + ds).toFixed(4)));
          currentBaseTransform.scaleZ = Math.max(0.1, Number(((currentBaseTransform.scaleZ || 1.14) + ds).toFixed(4)));
        }
        if (dsx) {
          currentBaseTransform.scaleX = Math.max(0.1, Number(((currentBaseTransform.scaleX || 1.14) + dsx).toFixed(4)));
        }
        if (dsz) {
          currentBaseTransform.scaleZ = Math.max(0.1, Number(((currentBaseTransform.scaleZ || 1.14) + dsz).toFixed(4)));
        }

        const targetObj = newKeyModel || CASE.case || CASE.group;
        applyBaseTransform(targetObj);
        emitBaseTransformUpdate();
      };

      window.resetBaseTransform = (target = "base") => {
        const clusterTarget = (target === "nav_cluster" || target === "home_end_pgup" || target === "pg_cluster")
          ? "nav_cluster"
          : (target === "rctl" || target === "right_control")
            ? "rctl"
            : target;
        if (clusterTarget && clusterTarget !== "base" && currentClusterOffsets[clusterTarget]) {
          currentClusterOffsets[clusterTarget] = { ...DEFAULT_CLUSTER_OFFSETS[clusterTarget] };
          applyKeyClusterOffsets();
          emitBaseTransformUpdate();
          return;
        }

        if (target === "all") {
          currentBaseTransform = { ...DEFAULT_BASE_TRANSFORM };
          currentClusterOffsets = {
            nav_cluster: { ...DEFAULT_CLUSTER_OFFSETS.nav_cluster },
            arrow_cluster: { ...DEFAULT_CLUSTER_OFFSETS.arrow_cluster },
            rctl: { ...DEFAULT_CLUSTER_OFFSETS.rctl },
          };
          applyKeyClusterOffsets();
          const targetObj = newKeyModel || CASE.case || CASE.group;
          applyBaseTransform(targetObj);
          emitBaseTransformUpdate();
          return;
        }

        currentBaseTransform = { ...DEFAULT_BASE_TRANSFORM };
        const targetObj = newKeyModel || CASE.case || CASE.group;
        applyBaseTransform(targetObj);
        emitBaseTransformUpdate();
      };

      window.switchKeyModel = (isNew) => {
        isCurrentNewModel = !!isNew;
        updateKeyVisibility(isCurrentNewModel);

        if (!isNew) {
          if (CASE.case) CASE.case.visible = true;
          if (CASE.group) CASE.group.visible = true;
          if (KEYS.group) KEYS.group.visible = true;
          if (newKeyModel) newKeyModel.visible = false;
          return;
        }

        if (newKeyModel) {
          if (CASE.case) CASE.case.visible = false;
          if (KEYS.group) KEYS.group.visible = true;
          newKeyModel.visible = true;
          applyBaseTransform(newKeyModel);
          emitBaseTransformUpdate();
          return;
        }

        if (isLoadingModel) return;
        isLoadingModel = true;

        const loader = new FBXLoader();
        const baseUrl = process.env.PUBLIC_URL || ".";
        loader.load(`${baseUrl}/new_keybase.fbx`, (object) => {
          newKeyModel = object;
          newKeyModel.name = "NEW_KEYBASE_MODEL";

          const bbox = new THREE.Box3().setFromObject(object);
          const size = new THREE.Vector3();
          bbox.getSize(size);

          if (size.x > 30) {
            object._baseScale = 0.03937;
          } else {
            object._baseScale = 1.0;
          }

          // Materials configuration for white, silver, and black
          const texLoader = new THREE.TextureLoader();
          const blackDiffuseTex = texLoader.load(`${baseUrl}/diffuse_black.png`, (t) => {
            t.wrapS = THREE.ClampToEdgeWrapping;
            t.wrapT = THREE.ClampToEdgeWrapping;
            if (THREE.SRGBColorSpace) {
              t.colorSpace = THREE.SRGBColorSpace;
            }
            t.needsUpdate = true;
          });

          const cubemap = CASE && CASE.cubemap ? CASE.cubemap : null;

          const whiteMat = new THREE.MeshPhysicalMaterial({
            color: 0xf6f6f2,
            roughness: 0.32,
            metalness: 0.05,
            clearcoat: 0.2,
            clearcoatRoughness: 0.15,
            envMap: cubemap,
            envMapIntensity: 0.6,
          });

          const chromeMat = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            roughness: 0.05,
            metalness: 0.98,
            clearcoat: 1.0,
            clearcoatRoughness: 0.05,
            envMap: cubemap,
            envMapIntensity: 1.5,
          });

          const blackGlassMat = new THREE.MeshPhysicalMaterial({
            color: 0x999999,
            map: blackDiffuseTex,
            emissive: 0xffffff,
            emissiveMap: blackDiffuseTex,
            emissiveIntensity: 0.38,
            roughness: 0.05,
            metalness: 0.25,
            clearcoat: 1.0,
            clearcoatRoughness: 0.04,
            envMap: cubemap,
            envMapIntensity: 1.5,
          });

          object.traverse((child) => {
            if (child.isMesh) {
              child.castShadow = true;
              child.receiveShadow = true;

              const name = (child.name || "").toLowerCase();
              if (name.includes("white")) {
                child.material = whiteMat;
              } else if (name.includes("silver")) {
                child.material = chromeMat;
              } else if (name.includes("black")) {
                // Generate planar UVs on black mesh for diffuse texture
                if (!child.geometry.attributes.uv) {
                  child.geometry.computeBoundingBox();
                  const b = child.geometry.boundingBox;
                  const pos = child.geometry.attributes.position;
                  const uvs = new Float32Array(pos.count * 2);
                  const rx = (b.max.x - b.min.x) || 1;
                  const ry = (b.max.y - b.min.y) || 1;
                  for (let i = 0; i < pos.count; i++) {
                    uvs[i * 2] = (pos.getX(i) - b.min.x) / rx;
                    uvs[i * 2 + 1] = (pos.getY(i) - b.min.y) / ry;
                  }
                  child.geometry.setAttribute("uv", new THREE.BufferAttribute(uvs, 2));
                  child.geometry.uvsNeedUpdate = true;
                }
                child.material = blackGlassMat;
              }
            }
          });

          applyBaseTransform(object);

          CASE.group.add(object);
          if (CASE.case) CASE.case.visible = false;
          if (KEYS.group) KEYS.group.visible = true;
          newKeyModel.visible = true;
          isLoadingModel = false;
          updateKeyVisibility(true);
          emitBaseTransformUpdate();
        }, undefined, (err) => {
          console.error("Error loading new_keybase.fbx:", err);
          isLoadingModel = false;
        });
      };
        

      //start render loop
      ThreeApp.add(KEYS);
      ThreeApp.tick();

      // Default view to New Model
      try {
        window.switchKeyModel(true);
        updateKeyVisibility(true);
        applyKeyClusterOffsets();
      } catch (e) {
        console.warn("Could not switch to new model by default:", e);
      }
    },
  });
};



function listObjs(scene) {
  const names = [];
  scene.traverse((object) => {
    if (object.name) { 
      names.push(object.name);
    }
  });
  return names;
}



function loadFBX(scene, file) {
  clearScene(scene);
        const loader = new FBXLoader();

        loader.load(file, (object) => {
          scene.add(object);
          logUVsFromObject(object);
        });
}






function exportFBX(scene) {
  exporter.parse(scene, function(result) {
          if(result instanceof ArrayBuffer) {
            // Khi xuất định dạng binary .glb
            saveArrayBuffer(result, 'scene.glb');
          } else {
            // Khi xuất định dạng .gltf JSON
            const output = JSON.stringify(result, null, 2);
            saveString(output, 'scene.gltf');
          }
        }, 
        function(error) {
          console.error('Lỗi khi xuất:', error);
        }, 
        { binary: true } // hoặc false cho JSON .gltf
        );

      
}


function logUVsFromObject(object) {
  object.traverse((child) => {
    if (child.isMesh) {
      const geometry = child.geometry;
      if (geometry && geometry.attributes && geometry.attributes.uv) {
        const uvAttr = geometry.attributes.uv;
        const uvs = [];
        for (let i = 0; i < uvAttr.count; i++) {
          uvs.push([uvAttr.getX(i), uvAttr.getY(i)]);
        }
      }
    }
  });
}




function clearScene(scene) {
  // Duyệt qua tất cả các đối tượng con trong scene
  scene.traverse(object => {
    if (object.geometry) {
      object.geometry.dispose(); // giải phóng geometry GPU
    }
    if (object.material) {
      if (Array.isArray(object.material)) {
        object.material.forEach(mat => mat.dispose()); // nhiều vật liệu
      } else {
        object.material.dispose(); // vật liệu đơn
      }
    }
  });

  // Xóa tất cả đối tượng khỏi scene
  while (scene.children.length > 0) {
    scene.remove(scene.children[0]);
  }
}








const exporter = new GLTFExporter();

function saveString(text, filename) {
  const blob = new Blob([text], {type: 'text/plain'});
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
}

function saveArrayBuffer(buffer, filename) {
  const blob = new Blob([buffer], {type: 'application/octet-stream'});
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
}







const exportCombinedTexturesAsImage = (textures,keys, filename) => {
  if (!textures || textures.length === 0) {
    console.warn('Không có texture để ghép');
    return;
  }

  // Giả sử tất cả canvas có cùng kích thước, lấy từ canvas đầu tiên
  const canvasWidth = textures[0].image.width;
  const canvasHeight = textures[0].image.height;

  // Số cột mong muốn trong bảng (có thể thay đổi)
  const cols = 10;
  const rows = Math.ceil(textures.length / cols);

  // Tạo canvas tổng để ghép
  const combinedCanvas = document.createElement('canvas');
  combinedCanvas.width = cols * canvasWidth;
  combinedCanvas.height = rows * canvasHeight;
  const ctx = combinedCanvas.getContext('2d');

  // Vẽ từng texture lên canvas tổng theo vị trí bảng
  textures.forEach((texture, index) => {
    if(keys.components[index])
    {
      const x = (index % cols) * canvasWidth;
      const y = Math.floor(index / cols) * canvasHeight;
      ctx.drawImage(texture.image, x, y, canvasWidth, canvasHeight);

      const text = keys.components[index].code || '';  // lấy code tương ứng hoặc chuỗi rỗng nếu không có
      ctx.fillText(text, x + 10, y + 30);
    }
  });

  // Xuất canvas tổng thành file ảnh
  combinedCanvas.toBlob((blob) => {
    if (!blob) {
      console.error('Lỗi khi tạo blob từ canvas tổng');
      return;
    }
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename || 'combined_textures.png';
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  }, 'image/png');
};

// Ví dụ gọi hàm với mảng texture cần xuất
const exportAllTexturesCombined = async (KEYS) => {
  let texturesToCombine = [];
  for (const k of KEYS.components) {
    const mtls = k.cap.material;
    if (mtls[1]?.map) texturesToCombine.push(mtls[1].map);
    if (mtls[3]?.map) texturesToCombine.push(mtls[3].map);
  }
  // Đợi render canvas xong nếu canvas thay đổi động (nếu cần)
  await new Promise(r => setTimeout(r, 100));
  exportCombinedTexturesAsImage(texturesToCombine, KEYS, 'all_textures_combined.png');
};


