import React, { useEffect, useRef, useState } from "react";
import { useDispatch } from "react-redux";
import Sidebar from "../components/sidebar/Sidebar";
import threeApp from "../three/index";
import store from "../store/store";
import {
  addCustomColorway,
  updateCustomColorway,
  setColorway,
} from "../store/slices/colorways";
import ThreeUtil from "../util/three";
import jsQR from "jsqr";

export default function Home() {
  const rootEl = useRef(null);
  const [showSidebar, setShowSidebar] = useState(true);
  const dispatch = useDispatch();

  useEffect(() => {
    threeApp(rootEl.current);
    if (rootEl.current) {
      rootEl.current.focus();
    }
  }, []);

  useEffect(() => {
    const handleBlur = () => {
      if (rootEl.current) {
        rootEl.current.focus();
      }
    };
    window.addEventListener("blur", handleBlur);
    return () => window.removeEventListener("blur", handleBlur);
  }, []);

  useEffect(() => {
    window.getKeySimDesignQr = () => {
      try {
        const state = store.getState();
        const activeColorway = state.colorways?.byId?.[state.colorways?.activeId];
        if (!activeColorway) return null;
        const code = JSON.stringify(activeColorway);
        const canvas = ThreeUtil.createQrCanvas(code, 256);
        const url = canvas ? canvas.toDataURL("image/png") : null;
        return {
          id: activeColorway.id,
          label: activeColorway.label || "Custom Keycaps",
          colorway: activeColorway,
          qrCode: code,
          qrDataUrl: url,
        };
      } catch (err) {
        console.error("Error generating KeySim QR:", err);
        return null;
      }
    };
  }, []);

  // Listen to messages from parent window (KeyHM Modal Header)
  useEffect(() => {
    const handleMsg = (event) => {
      if (!event?.data?.type) return;

      // 0. Response for design QR code
      if (event.data.type === "KEYSIM_GET_DESIGN_QR") {
        const qrInfo = window.getKeySimDesignQr ? window.getKeySimDesignQr() : null;
        window.parent?.postMessage({
          type: "KEYSIM_RESPONSE_CURRENT_QR",
          qrInfo
        }, "*");
      }

      // 1. Take 3D screenshot with embedded QR code
      if (event.data.type === "KEYSIM_TRIGGER_SCREENSHOT") {
        const state = store.getState();
        const activeColorway = state.colorways?.byId?.[state.colorways?.activeId];
        const qrData = activeColorway ? JSON.stringify(activeColorway) : "";
        document.dispatchEvent(
          new CustomEvent("screenshot", { detail: { qrData } })
        );
      }

      // 1.1 Switch between classic and new keyboard model
      if (event.data.type === "KEYSIM_SET_KEY_MODEL" || event.data.type === "KEYSIM_SWITCH_KEY_MODEL") {
        const isNew = !!event.data.isNew;
        if (typeof window.switchKeyModel === "function") {
          window.switchKeyModel(isNew);
        }
      }

      // 1.2 Adjust base position & rotation & scale
      if (event.data.type === "KEYSIM_ADJUST_BASE") {
        const { dx, dy, dz, drx, ds, dsx, dsz, target } = event.data;
        if (typeof window.adjustBaseTransform === "function") {
          window.adjustBaseTransform(dx || 0, dy || 0, dz || 0, drx || 0, ds || 0, dsx || 0, dsz || 0, target || "base");
        }
      }

      // 1.3 Reset base position & rotation
      if (event.data.type === "KEYSIM_RESET_BASE") {
        const { target } = event.data || {};
        if (typeof window.resetBaseTransform === "function") {
          window.resetBaseTransform(target || "base");
        }
      }

      // 1.4 Get current base transform
      if (event.data.type === "KEYSIM_GET_BASE_TRANSFORM") {
        if (typeof window.getBaseTransform === "function") {
          const tf = window.getBaseTransform();
          window.parent?.postMessage({
            type: "KEYSIM_BASE_TRANSFORM_UPDATE",
            transform: tf
          }, "*");
        }
      }

      // 2. Download QR code file
      if (event.data.type === "KEYSIM_TRIGGER_DOWNLOAD_QR") {
        const state = store.getState();
        const activeColorway = state.colorways?.byId?.[state.colorways?.activeId];
        if (!activeColorway) {
          window.parent?.postMessage(
            { type: "KEYSIM_ACTION_NOTIFY", success: false, message: "No design currently selected!" },
            "*"
          );
          return;
        }
        const code = JSON.stringify(activeColorway);
        const canvas = ThreeUtil.createQrCanvas(code, 256);
        if (canvas) {
          const url = canvas.toDataURL("image/png");
          const link = document.createElement("a");
          link.href = url;
          link.download = `${activeColorway.label || "keysim"}-qr.png`;
          document.body.appendChild(link);
          link.click();
          link.remove();
          window.parent?.postMessage(
            { type: "KEYSIM_ACTION_NOTIFY", success: true, message: `Downloaded QR code for "${activeColorway.label}"!` },
            "*"
          );
        }
      }

      // 3. Scan / Upload QR code image to restore design
      if (event.data.type === "KEYSIM_IMPORT_QR_IMAGE") {
        const dataUrl = event.data.dataUrl;
        if (!dataUrl) return;
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement("canvas");
          canvas.width = img.width;
          canvas.height = img.height;
          const ctx = canvas.getContext("2d");
          if (!ctx) {
            window.parent?.postMessage(
              { type: "KEYSIM_QR_IMPORT_RESULT", success: false, message: "Canvas image processing error" },
              "*"
            );
            return;
          }
          ctx.drawImage(img, 0, 0);
          const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          let result = jsQR(imgData.data, canvas.width, canvas.height);
          if (!result?.data && (canvas.width > 280 || canvas.height > 280)) {
            const cornerW = Math.min(canvas.width, 350);
            const cornerH = Math.min(canvas.height, 350);
            const cornerData = ctx.getImageData(0, 0, cornerW, cornerH);
            result = jsQR(cornerData.data, cornerW, cornerH);
          }
          if (!result?.data) {
            window.parent?.postMessage(
              { type: "KEYSIM_QR_IMPORT_RESULT", success: false, message: "No valid QR code found in the uploaded image!" },
              "*"
            );
            return;
          }
          try {
            const parsed = JSON.parse(result.data);
            if (!parsed?.swatches || typeof parsed.swatches !== "object") {
              window.parent?.postMessage(
                { type: "KEYSIM_QR_IMPORT_RESULT", success: false, message: "QR code does not contain a valid KeySim keyboard configuration!" },
                "*"
              );
              return;
            }
            const newId = parsed.id || `custom_${Date.now()}`;
            const normalized = {
              ...parsed,
              id: newId,
              label: parsed.label || "Imported QR Colorway",
            };
            dispatch(addCustomColorway(normalized));
            dispatch(updateCustomColorway(normalized));
            dispatch(setColorway(normalized.id));
            document.dispatchEvent(new CustomEvent("force_key_material_update"));
            window.parent?.postMessage(
              { type: "KEYSIM_QR_IMPORT_RESULT", success: true, name: normalized.label },
              "*"
            );
          } catch (e) {
            window.parent?.postMessage(
              { type: "KEYSIM_QR_IMPORT_RESULT", success: false, message: "Error parsing QR code data: " + e.message },
              "*"
            );
          }
        };
        img.onerror = () => {
          window.parent?.postMessage(
            { type: "KEYSIM_QR_IMPORT_RESULT", success: false, message: "Cannot open image file!" },
            "*"
          );
        };
        img.src = dataUrl;
      }
    };

    window.addEventListener("message", handleMsg);
    return () => window.removeEventListener("message", handleMsg);
  }, [dispatch]);

  return (
    <>
      {showSidebar && <Sidebar />}

      <div
        id="canvas-wrapper"
        ref={rootEl}
        tabIndex={0}
        role="region"
        aria-label="3d scene of keyboard"
      ></div>
    </>
  );
}
