import * as THREE from "three";
import Collection from "./collection";
import { subscribe } from "redux-subscriber";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { enableHighlight, disableHighlight } from "./key/materials";
import store from "../store/store";
import ColorUtil from "../util/color";
import ThreeUtil from "../util/three";
//import { CSS3DRenderer } from "three/examples/jsm/renderers/CSS3DRenderer.js";

const DEFAULT_RENDER_SETTINGS = {
  lightIntensity: 1.25,
  brightness: 1.05,
  contrast: 1.15,
  hue: 0.0,
  saturation: 1.18,
  lightness: 1.0,
};

export default class SceneManager extends Collection {
  constructor(options) {
    super();
    this.takeScreenshot = false;
    this.screenshotQrData = null;
    this.options = options || {};
    this.editing = false;
    this.scale = options.scale || 1;
    this.textureLoader = new THREE.TextureLoader();
    this.environmentTexture = null;
    this.el = options.el || document.body;
    this.init();
  }
  init() {
    this.scene = new THREE.Scene();
    //main renderer
    this.renderer = new THREE.WebGLRenderer({
      alpha: true,
      logarithmicDepthBuffer: true,
      antialias: true,
      powerPreference: "high-performance",
    });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.2;
    this.renderer.localClippingEnabled = true;
    this.renderer.setPixelRatio(window.devicePixelRatio);
    this.el.appendChild(this.renderer.domElement);
    //css renderer for dom elements in the scene
    // this.cssRenderer = new CSS3DRenderer();
    // this.el.appendChild(this.cssRenderer.domElement);

    //main setup
    this.setupCamera();
    this.setupControls();
    this.setupLights();
    this.applyRenderSettings(DEFAULT_RENDER_SETTINGS);
    this.syncSceneBackground(store.getState());
    this.resize();

    //mouse and raycaster
    this.mouse = new THREE.Vector2(-1000, -1000);
    this.raycaster = new THREE.Raycaster();
    this.raycaster.layers.set(1);

    //bind global events
    window.addEventListener("resize", (e) => this.resize(e), false);
    this.el.addEventListener("mousemove", (e) => this.move(e), false);
    this.el.addEventListener("click", (e) => this.mouseClick(e), false);
    this.el.addEventListener(
      "touchstart",
      (e) => {
        this.move(e);
        this.mouseClick(e);
      },
      false
    );
    document.addEventListener(
      "screenshot",
      (event) => {
        this.takeScreenshot = true;
        this.screenshotQrData = event?.detail?.qrData || null;
      },
      false
    );

    //some helpers for reading and setting orbit controls position / taking screenshots
    document.addEventListener("keydown", (e) => {
      // if (e.key === "F1") {
      // }
      // if (e.key === "F2") {
      //   this.camera.position.set(-7, 8, 9);
      //   this.controls.target.set(-3, -2, 1);
      // }
      // if (e.key === "F3") {
      //   this.takeScreenshot = true;
      // }
    });

    subscribe("colorways.editing", (state) => {
      this.editing = state.colorways.editing;
    });

    subscribe("renderSettings", (state) => {
      this.applyRenderSettings(state.renderSettings);
    });
    subscribe("settings.sceneColor", (state) => {
      this.syncSceneBackground(state);
    });
    subscribe("settings.sceneAutoColor", (state) => {
      this.syncSceneBackground(state);
    });
    subscribe("colorways.activeId", (state) => {
      this.syncSceneBackground(state);
    });
    subscribe("colorways.byId", (state) => {
      this.syncSceneBackground(state);
    });
  }
  get w() {
    return this.el.offsetWidth;
  }
  get h() {
    return this.el.offsetHeight;
  }
  get sidebarWidth() {
    let sb = document.getElementById("sidebar");
    return sb ? sb.offsetWidth : 0;
  }
  resize() {
    this.camera.aspect = this.w / this.h;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(this.w, this.h);
  }
  setupCamera() {
    this.camera = new THREE.PerspectiveCamera(60, this.w / this.h, 1, 1000);
    this.camera.position.set(-7.96, 12.52, 8.18);
  }
  setupControls() {
    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
    this.controls.maxPolarAngle = (Math.PI / 20) * 9.7;
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.25;
    this.controls.enableKeys = false;
    this.controls.maxDistance = 40;
    this.controls.target.set(-8.04, 0.54, -0.53);
    this.controls.update();

    this.postCameraInfo = () => {
      if (typeof window !== "undefined" && window.parent && window.parent !== window) {
        try {
          const camPos = {
            x: Number(this.camera.position.x.toFixed(2)),
            y: Number(this.camera.position.y.toFixed(2)),
            z: Number(this.camera.position.z.toFixed(2)),
          };
          const camTgt = {
            x: Number(this.controls.target.x.toFixed(2)),
            y: Number(this.controls.target.y.toFixed(2)),
            z: Number(this.controls.target.z.toFixed(2)),
          };
          window.parent.postMessage(
            {
              type: "KEYSIM_CAMERA_UPDATE",
              position: camPos,
              target: camTgt,
            },
            "*"
          );
        } catch (e) {}
      }
    };

    this.controls.addEventListener("change", () => {
      if (this.postCameraInfo) this.postCameraInfo();
    });
    setTimeout(() => { if (this.postCameraInfo) this.postCameraInfo(); }, 100);
    setTimeout(() => { if (this.postCameraInfo) this.postCameraInfo(); }, 500);
    setTimeout(() => { if (this.postCameraInfo) this.postCameraInfo(); }, 1200);
  }
  setupLights() {
    let ambiant = new THREE.AmbientLight("#ffffff", 2.2);
    this.scene.add(ambiant);

    // main radiant key light
    let primaryLight = new THREE.DirectionalLight("#fffdf5", 1.4);
    primaryLight.position.set(6, 14, 12);
    primaryLight.target.position.set(0, -2, 0);
    primaryLight.target.updateMatrixWorld();
    this.scene.add(primaryLight, primaryLight.target);

    // cool rim / fill light for high contrast definition
    let shadowLight = new THREE.DirectionalLight("#dbeafe", 0.7);
    shadowLight.position.set(-6, 8, -10);
    shadowLight.target.position.set(0, 0, 0);
    shadowLight.target.updateMatrixWorld();
    this.scene.add(shadowLight, shadowLight.target);

    // top highlight kicker for glossy specular highlights on legends & rotary knob
    let topLight = new THREE.DirectionalLight("#ffffff", 0.6);
    topLight.position.set(0, 16, 2);
    topLight.target.position.set(0, 0, 0);
    topLight.target.updateMatrixWorld();
    this.scene.add(topLight, topLight.target);

    this.lights = {
      ambient: ambiant,
      primary: primaryLight,
      shadow: shadowLight,
      top: topLight,
    };
    this.baseLightIntensity = {
      ambient: ambiant.intensity,
      primary: primaryLight.intensity,
      shadow: shadowLight.intensity,
      top: topLight.intensity,
    };

    //lighthelpers
    // let slh = new THREE.DirectionalLightHelper(shadowLight, 2);
    // let plh = new THREE.DirectionalLightHelper(primaryLight, 2);
    // slh.update();
    // plh.update();
    // this.scene.add(slh, plh);
  }
  getSceneBackgroundColor(state) {
    const fallback = "#202024";
    const activeId = state?.colorways?.activeId;
    const manualColor = state?.settings?.sceneColor || fallback;
    if (!state?.settings?.sceneAutoColor) {
      return manualColor;
    }
    return ColorUtil.getAccent(activeId) || manualColor || fallback;
  }
  createEnvironmentTexture(color) {
    const threeColor = new THREE.Color(color);
    const data = new Uint8Array([
      Math.round(threeColor.r * 255),
      Math.round(threeColor.g * 255),
      Math.round(threeColor.b * 255),
      Math.round(threeColor.r * 255),
      Math.round(threeColor.g * 255),
      Math.round(threeColor.b * 255),
    ]);
    const texture = new THREE.DataTexture(data, 2, 1, THREE.RGBFormat);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.mapping = THREE.EquirectangularReflectionMapping;
    texture.needsUpdate = true;
    return texture;
  }
  syncSceneBackground(state) {
    const color = this.getSceneBackgroundColor(state);
    const sceneColor = new THREE.Color(color);
    if (this.environmentTexture) {
      this.environmentTexture.dispose();
    }
    this.environmentTexture = this.createEnvironmentTexture(color);
    this.scene.background = sceneColor;
    this.scene.environment = this.environmentTexture;
    this.renderer.setClearColor(sceneColor, 1);
    this.scene.traverse((obj) => {
      if (!obj.isMesh || !obj.material) return;
      const materials = Array.isArray(obj.material) ? obj.material : [obj.material];
      materials.forEach((material) => {
        if ("envMapIntensity" in material) {
          material.needsUpdate = true;
        }
      });
    });
  }
  applyRenderSettings(settings) {
    const s = { ...DEFAULT_RENDER_SETTINGS, ...(settings || {}) };

    const lightIntensity = Number.isFinite(Number(s.lightIntensity))
      ? Number(s.lightIntensity)
      : DEFAULT_RENDER_SETTINGS.lightIntensity;

    if (this.lights && this.baseLightIntensity) {
      this.lights.ambient.intensity = this.baseLightIntensity.ambient * lightIntensity;
      this.lights.primary.intensity = this.baseLightIntensity.primary * lightIntensity;
      this.lights.shadow.intensity = this.baseLightIntensity.shadow * lightIntensity;
    }

    const brightness = Number.isFinite(Number(s.brightness))
      ? Number(s.brightness)
      : DEFAULT_RENDER_SETTINGS.brightness;
    const contrast = Number.isFinite(Number(s.contrast))
      ? Number(s.contrast)
      : DEFAULT_RENDER_SETTINGS.contrast;
    const hue = Number.isFinite(Number(s.hue))
      ? Number(s.hue)
      : DEFAULT_RENDER_SETTINGS.hue;
    const saturation = Number.isFinite(Number(s.saturation))
      ? Number(s.saturation)
      : DEFAULT_RENDER_SETTINGS.saturation;
    const lightness = Number.isFinite(Number(s.lightness))
      ? Number(s.lightness)
      : DEFAULT_RENDER_SETTINGS.lightness;

    if (this.renderer?.domElement) {
      this.renderer.domElement.style.filter =
        `brightness(${brightness}) brightness(${lightness}) ` +
        `contrast(${contrast}) saturate(${saturation}) hue-rotate(${hue}deg)`;
    }
  }
  mouseClick(e) {
    if (this.editing) {
      if (this.intersectedObj) {
        let event = new CustomEvent("key_painted", {
          detail: this.intersectedObj.name,
        });
        document.dispatchEvent(event);
      }
    } else {
      if (this.intersectedObj && window.KEYS && window.KEYS.components) {
        const k = window.KEYS.components.find(
          (c) => c.cap === this.intersectedObj || (c.cap && c.cap.name === this.intersectedObj.name)
        );
        if (k && typeof k.setState === "function") {
          k.setState(3); // KEYSTATES.MOVING_DOWN
          setTimeout(() => {
            if (typeof k.setState === "function") k.setState(2); // KEYSTATES.MOVING_UP
          }, 120);
        }
      }
    }
  }
  move(e) {
    e.preventDefault();
    let isTouch = e.type === "touchstart";
    let l = (isTouch ? e.touches[0].clientX : e.clientX) - this.sidebarWidth;
    let t = (isTouch ? e.touches[0].clientY : e.clientY) - 0;
    this.mouse.x = (l / this.w) * 2 - 1;
    this.mouse.y = -(t / this.h) * 2 + 1;
  }
  deactivateIntersection() {
    if (!this.intersectedObj) return;
    disableHighlight(this.intersectedObj);
    this.intersectedObj = undefined;
  }
  activateIntersection(obj) {
    document.body.classList.add("intersecting-key");
    this.isIntersecting = true;
    this.intersectedObj = obj;
    if (this.editing) enableHighlight(obj);
  }
  checkIntersections() {
    let intersects = this.raycaster.intersectObjects(this.scene.children, true);
    //no intersections
    if (!intersects.length) {
      this.isIntersecting = false;
      this.deactivateIntersection();
      document.body.classList.remove("intersecting-key");
      return;
    }
    //same obj dont do anything
    if (this.intersectedObj === intersects[0].object) return;
    //reset old object
    this.deactivateIntersection();
    //not a valid obj
    let ignored = intersects[0]?.object.name === "IGNORE";
    if (ignored) return;
    //activate new obj
    this.activateIntersection(intersects[0].object);
  }
  render() {
    this.update();
    const moved = this.controls.update();
    if (moved && this.postCameraInfo) {
      this.postCameraInfo();
    }
    this.raycaster.setFromCamera(this.mouse, this.camera);
    this.checkIntersections();
    this.renderer.render(this.scene, this.camera);
    // let x = this.camera.position.x;
    // let y = this.camera.position.y;
    // let z = this.camera.position.z;
    //this.camera.position.multiplyScalar(this.scale);
    //this.cssRenderer.render(this.scene, this.camera);
    //this.camera.position.set(x, y, z);
  }
  tick() {
    this.render();
    if (this.takeScreenshot) {
      ThreeUtil.getSceneScreenshot(this.renderer, this.screenshotQrData);
      this.takeScreenshot = false;
      this.screenshotQrData = null;
    }
    requestAnimationFrame(this.tick.bind(this));
  }
}
