import React, { useEffect } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import {
  fetchColorways,
  selectAvailableColorways,
  setColorway,
} from "./store/slices/colorways";
import ColorUtil, { getTransparentColor } from "./util/color";
import Home from "./pages/Home";
import "./App.scss";

import * as colorwaysActions from "./store/slices/colorways";
import * as settingsActions from "./store/slices/settings";
import { fetchRenderSettings } from "./store/slices/renderSettings";

export default function App() {
  const dispatch = useDispatch();
  const available = useSelector(selectAvailableColorways);
  const colorway_id = useSelector(colorwaysActions.selectColorway);
  const sceneAutoColor = useSelector(settingsActions.selectSceneAutoColor);
  const sceneColor = useSelector(settingsActions.selectSceneColor);
  const highContrast = useSelector(settingsActions.selectHighContrast);

  useEffect(() => {
    console.log("Get coloways!");
    dispatch(fetchColorways());
    dispatch(fetchRenderSettings());
  }, []);

  useEffect(() => {
    if (!available || available.length === 0) return;
    if (colorway_id && available.some((cw) => cw.id === colorway_id)) return;
    dispatch(setColorway(available[0].id));
  }, [available, colorway_id, dispatch]);

  const getAccent = () => {
    return ColorUtil.getUiAccent(colorway_id);
  };

  const getSceneColor = () => {
    return sceneAutoColor ? ColorUtil.getAccent(colorway_id) : sceneColor;
  };

  const uiColors = {
    "--main": "#202024",
    "--dark-1": "#202024",
    "--dark-2": "#202024",
    "--light-1": "#38383f",
    "--light-2": "#9c9ca7",
    "--light-3": "#e0e0e3",
    "--accent": getAccent(),
    "--sceneColor": getSceneColor(),
    "--accent-transparent": getTransparentColor(getAccent()),
    "--compliment": ColorUtil.getUiCompliment(colorway_id),
    "--accent-text": ColorUtil.getUiAccentText(colorway_id),
  };

  const uiColorsHC = {
    "--main": "#000000",
    "--dark-1": "#202024",
    "--dark-2": "#202024",
    "--light-1": "#202024",
    "--light-2": "#cccccc",
    "--light-3": "#ffffff",
    "--accent": getAccent(),
    "--sceneColor": getSceneColor(),
    "--accent-transparent": getTransparentColor(getAccent()),
    "--compliment": ColorUtil.getUiCompliment(colorway_id),
    "--accent-text": "#000000",
  };

  return (
    <div className="App" style={highContrast ? uiColorsHC : uiColors}>
      <Router>
        <Home />
        <Routes>
          <Route path="/" element={<></>} />
        </Routes>
      </Router>
    </div>
  );
}
